mapper.select:
SELECT COUNT(*) OVER() AS TOTAL_RECORD_COUNT, RELATE_IMAGE_PATH, RELATE_IMAGE_NM, MENU_PAGE_TARGET, MENU_POPUPNFO, MENU_PRIVACY, MENU_ICON_TYPE, MENU_NO, MENU_ORDR, MENU_NM, UPPER_MENU_NO, MENU_DC, PROGRM_FILE_NM, PROGRM_KOREAN_NM, URL, LEVEL, ctg_path, MENU_CLASS FROM ( WITH RECURSIVE cte AS ( -- [1] Anchor Member (최상위 메뉴) SELECT a.MENU_NO, a.MENU_ORDR, a.MENU_NM, a.UPPER_MENU_NO, a.MENU_DC, a.PROGRM_FILE_NM, b.PROGRM_KOREAN_NM, b.URL, a.RELATE_IMAGE_PATH, a.RELATE_IMAGE_NM, a.MENU_PAGE_TARGET, a.MENU_POPUPNFO, a.MENU_PRIVACY, a.MENU_USEYN, a.MENU_CLASS, a.MENU_ICON_TYPE, 1 as LEVEL, CAST(a.MENU_NO AS VARCHAR(100)) as ctg_path FROM COMTNMENUINFO a JOIN COMTNPROGRMLIST b ON a.PROGRM_FILE_NM = b.PROGRM_FILE_NM WHERE a.UPPER_MENU_NO IS NULL
UNION ALL -- [2] Recursive Member (하위 메뉴) - ctg_path를 동일하게 VARCHAR(100)으로 캐스팅 SELECT a.MENU_NO, a.MENU_ORDR, a.MENU_NM, a.UPPER_MENU_NO, a.MENU_DC, a.PROGRM_FILE_NM, b.PROGRM_KOREAN_NM, b.URL, a.RELATE_IMAGE_PATH, a.RELATE_IMAGE_NM, a.MENU_PAGE_TARGET, a.MENU_POPUPNFO, a.MENU_PRIVACY, a.MENU_USEYN, a.MENU_CLASS, a.MENU_ICON_TYPE, c.LEVEL + 1, CAST(CONCAT(c.ctg_path, '-', a.MENU_NO) AS VARCHAR(100)) as ctg_path FROM COMTNMENUINFO a JOIN COMTNPROGRMLIST b ON a.PROGRM_FILE_NM = b.PROGRM_FILE_NM JOIN cte c ON a.UPPER_MENU_NO = c.MENU_NO WHERE 1=1
AND a.MENU_USEYN = #{params.searchUseyn}
) -- [3] 최종 조회부 SELECT DISTINCT RELATE_IMAGE_PATH, RELATE_IMAGE_NM, MENU_PAGE_TARGET, MENU_POPUPNFO, MENU_PRIVACY, MENU_NO, MENU_ORDR, MENU_NM, UPPER_MENU_NO, MENU_DC, PROGRM_FILE_NM, PROGRM_KOREAN_NM, URL, LEVEL, ctg_path, MENU_CLASS, MENU_ICON_TYPE FROM cte WHERE 1=1
AND MENU_NM LIKE CONCAT('%', #{params.searchKeyword}, '%')
ORDER BY ctg_path ASC, MENU_ORDR ASC ) X

